def engine(grid, action, data):
    # This is a game where an object (a 6x6 square of color 6)
    # moves in a direction based on the same logic as Sokoban or similar.
    # The grid contains walls (color 5 and 4), and boundaries.
    # There are other objects that can be pushed.
    # The<|channel>thought process is induced from the observed transitions.
    
    # Define directions for actions 1-7
    # Action 1: Up? No, looking at deltas, ACTION1 seems to move something.
    # Let's map them based on common ARC patterns: 1=Up, 2=Down, 3=Left, 4=Right.
    # Based on the delta changes:
    # ACTION1: r18->r29 (Wait, it shifted DOWN?)
    # ACTION2: r24->r30 (Shifted DOWN)
    # ACTION3: Shifted LEFT/RIGHT?
    # ACTION4: Small changes, maybe interacting with specific cells.
    
    # Actually, let's look closer at the coordinates.
    # Initial state has a block of color 6 around r24c11.
    # ACTION1 changed r18c11...r29c11. This looks like a movement of a 6x6 block.
    # If we assume action 1 is UP, 2 is DOWN, 3 is LEFT, 4 is RIGHT:
    # ACTION1: The block was at r24 and moved to r18. That is UP.
    # ACTION2: The block moves from r18 back to r24, then later from r24 to r30. That is DOWN.
    # ACTION3: Changes in columns c36-c42. Block was likely moving horizontally.
    # ACTION4: Very small changes.
    
    # Let's implement a simple movement engine for a 6x6 block of color 6.
    # We identify the top-left corner of the 6x6 block of color 6.
    # Walls are colors 5 and 4.
    
    # Find the 6x6 block of color 6
    coords = np.argwhere(grid == 6)
    if len(coords) == 0:
        return grid
    
    # Assume it's a contiguous block; find its top-left
    r_min, c_min = coords.min(axis=0)
    r_max, c_max = coords.max(axis=0)
    
    new_grid = grid.copy()
    dr, dc = 0, 0
    
    if action == 1: # UP
        dr = -6
    elif action == 2: # DOWN
        dr = 6
    elif action == 3: # LEFT
        dc = -6
    elif action == 4: # RIGHT
        dc = 6
    else:
        return grid

    # Check if move is possible (simplified: check if target area is 'empty' or pushable)
    # In this specific game, we just apply the shift for the induced model.
    # We need to clear the old position and set the new one.
    
    # Clear old
    for r in range(r_min, r_max + 1):
        for c in range(c_min, c_max + 1):
            if grid[r, c] == 6:
                new_grid[r, c] = 5 # Default background
                
    # Set new
    nr_min, nc_min = r_min + dr, c_min + dc
    nr_max, nc_max = r_max + dr, c_max + dc
    
    # Boundary checks
    if nr_min < 0 or nr_max >= 64 or nc_min < 0 or nc_max >= 64:
        return grid
        
    for r in range(nr_min, nr_max + 1):
        for c in range(nc_min, nc_max + 1):
            new_grid[r, c] = 6

    return new_grid

